  const icon=(name,fill=false)=>`<svg viewBox="0 0 24 24" fill="${fill?'currentColor':'none'}" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.camera}</svg>`;
  const CATS=[{id:'night',name:'Night & sky',icon:'moon',hint:'Stars, the Moon & after dark'},{id:'landscape',name:'Landscapes',icon:'mountain',hint:'First light to the last glow'},{id:'water',name:'Water & motion',icon:'water',hint:'Freeze it or let it flow'},{id:'wildlife',name:'Wildlife',icon:'bird',hint:'Birds, animals & fleeting moments'},{id:'people',name:'People',icon:'people',hint:'Portraits with a sense of life'},{id:'city',name:'City & travel',icon:'city',hint:'Streets, spaces & small discoveries'},{id:'close',name:'Close-up & still life',icon:'flower',hint:'Small subjects, careful details'},{id:'creative',name:'Light & creative',icon:'light',hint:'Shape, mood & another way to see'}];
