  function nav(){const page=route()[0],active=page==='scene'?'scenes':page;$('#desktop-nav').innerHTML=NAV.map(([id,ic,label])=>`<a class="nav-item ${id===active?'active':''}" href="#${id}"${id===active?' aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='scenes'?'<span class="count">'+D.length+'</span>':id==='saved'&&state.favourites.length?'<span class="count">'+state.favourites.length+'</span>':''}</a>`).join('');$('#mobile-nav').innerHTML=[['home','home','Home'],['scenes','grid','Scenes'],['rescue','rescue','Rescue'],['tools','tools','Tools'],['saved','bookmark','Saved']].map(([id,ic,label])=>`<a href="#${id}" class="bottom-item ${active===id?'active':''}"${active===id?' aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('');$('#section-name').textContent=NAV.find(n=>n[0]===active)?.[2]||(active==='settings'?'Kit & app settings':active==='about'?'About the guide':'Your field companion');$('#settings-link').innerHTML=icon('settings');}
  function sourceLinks(sources){return `<div class="source-links">${(sources||[]).filter(s=>/^https:\/\//.test(s.url)).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`).join('')}</div>`;}
